"""Low level user interaction functions for the SIM KV GENERATOR pane in the SimDialogs test tool app.
Used by the SimDialogs page object class"""

from .objects.sim_dialogs_objects import SimDialogsObjects
from . import sim_dialog_main_functions as SimDialogMainFuncs
from interops.libraries.squish_actions import CommonActions
import interops.libraries.desktop.decorators as deco
from interops.libraries.squish_actions.constants import SIMDIALOGS_APP_NAME


@deco.set_separate_app_context(application_name=SIMDIALOGS_APP_NAME)
def check_sim_kv_generator_hand_switch_preparatory_checkbox() -> None:
    """Locates the main Sim Dialogs window > then left mouse click on the Hand Switch Preparatory Checkbox only if its enabled and unchecked
    """
    if SimDialogMainFuncs.find_main_sim_dialogs_window() and not CommonActions.get_checkbox_state(SimDialogsObjects.sim_KV_Generator_Hand_Switch_Preparatory_Checkbox):
        CommonActions.left_click_object_no_move(SimDialogsObjects.sim_KV_Generator_Hand_Switch_Preparatory_Checkbox)

@deco.set_separate_app_context(application_name=SIMDIALOGS_APP_NAME)
def uncheck_sim_kv_generator_hand_switch_preparatory_checkbox() -> None:
    """Locates the main Sim Dialogs window > then left mouse click on the Hand Switch Preparatory Checkbox only if its enabled and checked
    """
    if SimDialogMainFuncs.find_main_sim_dialogs_window() and CommonActions.get_checkbox_state(SimDialogsObjects.sim_KV_Generator_Hand_Switch_Preparatory_Checkbox):
        CommonActions.left_click_object_no_move(SimDialogsObjects.sim_KV_Generator_Hand_Switch_Preparatory_Checkbox)

